<?php

declare(strict_types=1);

namespace Tests\Unit\Content;

use App\Content\Blocks\EventDate;
use App\Content\Blocks\Inline;
use App\Content\Blocks\Urls;
use App\Content\Markdown;
use PHPUnit\Framework\Attributes\DataProvider;

/** Fixtures generated by the TS implementation for the smaller pure modules. */
final class HelpersParityTest extends FixtureTestCase
{
    public static function markdownCases(): array
    {
        return self::cases('markdown');
    }

    public static function urlCases(): array
    {
        return self::cases('urls');
    }

    public static function videoCases(): array
    {
        return self::cases('video-urls');
    }

    public static function inlineCases(): array
    {
        return self::cases('inline');
    }

    public static function paragraphCases(): array
    {
        return self::cases('paragraphs');
    }

    public static function eventDateCases(): array
    {
        return self::cases('event-date');
    }

    #[DataProvider('markdownCases')]
    public function test_markdown(array $case): void
    {
        $this->assertSame($case['html'], Markdown::parseMarkdown($case['input']));
        $this->assertSame($case['text'], Markdown::stripMarkdown($case['input']));
    }

    #[DataProvider('urlCases')]
    public function test_url_filters(array $case): void
    {
        $this->assertSame($case['safeHref'], Urls::safeHref($case['input']));
        $this->assertSame($case['safeImageSrc'], Urls::safeImageSrc($case['input']));
        if ($case['safeHref'] !== null) {
            $this->assertSame($case['isExternal'], Urls::isExternalHref($case['safeHref']));
        }
        $this->assertSame($case['video'], Urls::parseVideoUrl($case['input']));
    }

    #[DataProvider('videoCases')]
    public function test_video_urls(array $case): void
    {
        $this->assertSame($case['video'], Urls::parseVideoUrl($case['input']));
    }

    #[DataProvider('inlineCases')]
    public function test_inline_markup(array $case): void
    {
        $this->assertSame($case['html'], Inline::inlineToHtml($case['input']));
        $this->assertSame($case['text'], Inline::inlineToText($case['input']));
        $this->assertSame($case['escaped'], Inline::escapeInline($case['input']));
        $this->assertSame($case['paragraphs'], Inline::paragraphsOf($case['input']));
    }

    #[DataProvider('paragraphCases')]
    public function test_paragraph_splitting(array $case): void
    {
        $this->assertSame($case['paragraphs'], Inline::paragraphsOf($case['input']));
    }

    #[DataProvider('eventDateCases')]
    public function test_event_dates(array $case): void
    {
        $date = EventDate::parseEventDate($case['input']);
        $this->assertSame($case['date'], $date);
        if ($date !== null) {
            $this->assertSame($case['day'], EventDate::formatEventDay($date));
            $this->assertSame($case['time'], EventDate::formatEventTime($date));
        }
    }

    public function test_event_date_keys_order_like_the_ts_keys(): void
    {
        $early = EventDate::parseEventDate('2026-08-15T08:00');
        $late = EventDate::parseEventDate('2026-08-15T10:00');
        $next = EventDate::parseEventDate('2026-08-16');
        $this->assertLessThan(EventDate::eventDateKey($late), EventDate::eventDateKey($early));
        $this->assertLessThan(EventDate::eventDateKey($next), EventDate::eventDateKey($late));
        $this->assertSame(EventDate::eventDateKey(EventDate::parseEventDate('2026-08-15')), EventDate::eventDateKey(EventDate::parseEventDate('2026-08-15T00:00')));
    }
}
